#include <stdio.h>

struct student {
    char name[16];
    double gpa;
};

int main(void) {
    struct student s[3];
    for (int i = 0; i < 3; i++)
        scanf("%15s %lf", s[i].name, &s[i].gpa);
    int best = 0;
    for (int i = 1; i < 3; i++)
        if (s[i].gpa > s[best].gpa)
            best = i;
    printf("Best: %s (%.2f)\n", s[best].name, s[best].gpa);
    return 0;
}
